for _,set in ipairs(places)do
 for variation=1,3 do
  local id=set.environment..'-0'..variation..'-16x9'
  metadata[id]={inherits='meadow-perspective-16x9',composition_id=id,horizon_y=set.horizons[variation]}
  local mound='art/source/mound-'..set.day[variation]..'.png'
  local night='art/source/mound-'..set.night[variation]..'.png'
  compositions[#compositions+1]={id=id,environment=set.environment,variation=variation,
   aspect_ratio='16:9',quality='HD',metadata=id,background='art/source/'..id..'.png',
   backgrounds={day='art/source/'..id..'.png',night='art/source/'..id..'-night.png'},
   source_rect=set.source_rects and set.source_rects[variation]or nil,
   night_source_rect=set.night_source_rects and set.night_source_rects[variation]or nil,
   mounds={player=mound,opponent=mound},night_mounds={player=night,opponent=night}}
 end
end
