 if entry.id=='hotel-room-3-16x9'then entry.source_rect={x=58.9955564444,y=65.8700000000,width=1554.0088871111,height=874.1299990000}end
 if entry.id=='ship_captain-room-2-16x9'then entry.source_rect={x=67.3600008889,y=75.2800000000,width=1537.2799982222,height=864.7199990000}end
 if entry.id=='village-03-9x19_5'then entry.night_source_rect={x=0.1153848462,y=0.5000000000,width=851.7692303077,height=1845.4999990000}end
