-- Resolve dynamically assembled legacy names into the organized source tree.
local function organized(path)
 local name=type(path)=='string' and path:match('^art/source/(.+)$')
 if not name then return path end
 if name:match('^mound%-')then
  local material=assert(name:match('^mound%-(.-)%-%d+'),'Unclassified mound')
  return 'art/mounds/'..material..'/'..name
 end
 local location=assert(name:match('^(.-)%-%d+%-'),'Unclassified location')
 local aspect=assert(name:match('%-(%d+x[%d_]+)'),'Unclassified size')
 return 'art/gen1/'..aspect..'/'..location..'/'..name
end
for _,entry in ipairs(compositions)do
 entry.background=organized(entry.background)
 for _,field in ipairs({'backgrounds','mounds','night_mounds'})do
  for key,path in pairs(entry[field]or{})do entry[field][key]=organized(path)end
 end
end
return {metadata=metadata,compositions=compositions}
